import { useState } from "react";
import "./App.css";

const initialTransactions = [
    {
        type: "deposit",
        amount: 1000,
        date: Date("1/1/2025"),
    },
    {
        type: "buy",
        stock: "TSLA",
        shares: 10,
        price: 274,
        amount: 2740,
        date: Date("1/2/2025"),
    },
];

function App() {
    const [transactions, setTransactions] = useState([]);
    const [balance, setBalance] = useState(0);

    function createTransaction(type, stock, shares, price, amount, date) {}

    return (
        <div className="App">
            <h1>Trading Journal</h1>
            <Balances balance={balance} />
            <TradeForm />
            <DepositAndWithdrawalForm />
            <TransactionTable />
            <TradesTable />
        </div>
    );
}

function Balances({ balance }) {
    return (
        <div>
            <label>Account Balance</label>
            <input type="text" disabled value={balance} />
        </div>
    );
}

function TradeForm() {
    const [transactionType, setTransactionType] = useState("buy");
    function handleSubmit(e) {
        e.preventDefault();
        console.log(transactionType);
    }

    return (
        <form className="form" onSubmit={(e) => handleSubmit(e)}>
            <h2>Enter a Trade</h2>
            <div>
                <input
                    type="radio"
                    id="buy"
                    value="buy"
                    checked={transactionType === "buy"}
                    onChange={() => setTransactionType("buy")}
                />
                <label htmlFor="buy">Buy</label>
                <input
                    type="radio"
                    id="sell"
                    value="sell"
                    checked={transactionType === "sell"}
                    onChange={() => setTransactionType("sell")}
                />
                <label htmlFor="sell">Sell</label>
            </div>
            <div>
                <label>Stock</label>
                <input type="text" />
            </div>
            <div>
                <label>Shares</label>
                <input type="text" />
            </div>
            <div>
                <label>Price</label>
                <input type="text" />
            </div>
            <div>
                <label>Total</label>
                <input type="text" disabled />
            </div>
            <button>Submit</button>
        </form>
    );
}

function DepositAndWithdrawalForm() {
    const [transactionType, setTransactionType] = useState("deposit");
    function handleSubmit(e) {
        e.preventDefault();
        console.log(transactionType);
    }
    return (
        <form className="form" onSubmit={(e) => handleSubmit(e)}>
            <h2>Deposit or Withdraw</h2>
            <div>
                <input
                    type="radio"
                    id="deposit"
                    value="deposit"
                    checked={transactionType === "deposit"}
                    onChange={() => setTransactionType("deposit")}
                />
                <label htmlFor="deposit">Deposit</label>
                <input
                    type="radio"
                    id="withdraw"
                    value="withdraw"
                    checked={transactionType === "withdraw"}
                    onChange={() => setTransactionType("withdraw")}
                />
                <label htmlFor="withdraw">Withdraw</label>
            </div>
            <div>
                <label>Amount</label>
                <input type="text" />
            </div>
            <button>Submit</button>
        </form>
    );
}

function TransactionTable() {
    return (
        <div>
            <h2>Transactions</h2>
            <table></table>
        </div>
    );
}

function TradesTable() {
    return (
        <div>
            <h2>Trades</h2>
            <table></table>
        </div>
    );
}

export default App;
